    (135, "fact", "How much did training-time perturbations raise balanced accuracy and AUROC in the CBraMod EEG workload comparison?", "Balanced accuracy rose from 65.98% to 71.62% and AUROC from 0.768 to 0.805.", ["65.98% to 71.62% BA", "0.768 to 0.805 AUROC"], "The resulting CBraMod comparison increases BA from 65.98% to 71.62% and AUROC from 0.768 to 0.805.", "CBraMod"),
    (136, "paraphrase", "How were text conditions obtained for the video-based FAIR-Play and 360 Youtube-Binaural recordings?", "GPT-4o generated descriptions of each sound source's location from the videos.", ["GPT-4o", "descriptions of sound source locations"], "using GPT-4o", "FAIR-Play"),
    (137, "fact", "Which SMAC maps are used in the value-based evaluation that compares against Ft-QMIX, QPLEX and VAST?", "3s_vs_5z, 5m_vs_6m and 3s5z_vs_3s6z.", ["3s_vs_5z", "5m_vs_6m", "3s5z_vs_3s6z"], "with three representative maps: 3s_vs_5z, 5m_vs_6m and 3s5z_vs_3s6z", "SMAC"),
    (138, "fact", "What batch sizes are used for progressive distillation, LCM and DMD2 on SSD1B in the distillation experiments?", "224 for progressive distillation, 360 for LCM and 7 for DMD2.", ["224 progressive distillation", "360 LCM", "7 DMD2"], "on a batch size of 224 in case of progressive distillation, 360 in case of LCM and 7 in case of DMD2 on SSD1B", "SSD1B"),
    (140, "topical", "How can the action space in reinforcement learning for job shop scheduling allow several assignments at once?", "It is defined as the power set of feasible job-machine pairs in which no machine gets more than one job at a time.", ["power set of job-machine pairs", "no machine assigned more than one job"], "This formulation allows multiple job-machine assignments to be made at once", None),
    (142, "explain", "What does Test-Time Reinforcement Learning add to the LADDER framework?", "It extends LADDER to inference time, enabling dynamic adaptation to challenging problems during testing.", ["extends to inference time", "adapts during testing"], "Test-Time Reinforcement Learning (TTRL) extends our LADDER framework to inference time", "LADDER"),
    (145, "explain", "What are the two objectives of RoAR-VAE, and what does each one capture?", "RobustAlign captures semantic structure and RobustRecon captures fine-grained spatial and appearance details.", ["RobustAlign for semantic structure", "RobustRecon for spatial and appearance details"], "We realize this principle with RobustAlign for semantic structure and RobustRecon for fine-grained spatial and appearance details.", "RoAR-VAE"),
    (146, "paraphrase", "What explains why a transformer's ridge behaviour appears only for a while during training?", "The transformer navigates a tradeoff between loss and complexity that evolves over training.", ["tradeoff between loss and complexity", "evolves over training"], "we explain transient ridge as the transformer navigating a tradeoff between loss and complexity that evolves over training", "ridge"),
    (148, "explain", "What loss is proposed for simple fine-tuning in few-shot drug discovery?", "A regularized quadratic-probe loss based on the Mahalanobis distance, optimized by block-coordinate descent.", ["regularized quadratic-probe loss", "Mahalanobis distance"], "regularized quadratic-probe loss", "drug discovery"),
    (149, "paraphrase", "What is the IC2D bench built to test?", "It is a test bench for analysing the performance of actuators and controllers at the joint level.", ["analyses actuators and controllers", "at the joint level"], "is a test bench designed to allow the performance analysis of different actuators and controllers at the joint level", "IC2D"),
    (141, "topical", "Why is multimodal federated learning harder than unimodal federated learning?", "Modalities differ in dimensionality, sampling frequency and relevance, so heterogeneity, privacy and efficiency constraints combine across clients.", ["modalities differ in structure", "modalities are distributed across clients"], "These modalities differ in dimensionality, sampling frequency, and relevance to the learning task.", None),
